<?php $files = ['resources/views/layouts/frontend.blade.php', 'resources/views/frontend/partials/header.blade.php', 'resources/views/frontend/home.blade.php']; foreach ($files as $f) { $content = file_get_contents($f); if (substr($content, 0, 3) == pack('CCC', 0xef, 0xbb, 0xbf)) { file_put_contents($f, substr($content, 3)); echo 'BOM stripped from ' . $f . PHP_EOL; } else { echo 'No BOM in ' . $f . PHP_EOL; } }
